1	/**
2	 * NexiFy Chatbot Knowledge Base API
3	 * Cloudflare Pages Function — replaces chatbot/api.php
4	 *
5	 * Handles the same endpoints as the original PHP:
6	 *   GET  ?action=search&q=...    — keyword search
7	 *   GET  ?action=category&cat=   — entries by category
8	 *   GET  ?action=all             — full knowledge base
9	 *   GET  ?action=faq             — all FAQ entries
10	 *   GET  ?action=service&name=   — specific service info
11	 *   GET  ?action=contact         — contact information
12	 *   POST ?action=chat            — chatbot query (best answer)
13	 */
14	
15	const CORS_HEADERS = {
16	  'Access-Control-Allow-Origin': '*',
17	  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
18	  'Access-Control-Allow-Headers': 'Content-Type',
19	  'Content-Type': 'application/json; charset=utf-8',
20	};
21	
22	export async function onRequest(context) {
23	  const { request, env } = context;
24	
25	  // ── Preflight ──────────────────────────────────────────────
26	  if (request.method === 'OPTIONS') {
27	    return new Response(null, { status: 200, headers: CORS_HEADERS });
28	  }
29	
30	  // ── Load knowledge base from static asset ─────────────────
31	  let kb;
32	  try {
33	    const url     = new URL(request.url);
34	    const kbUrl   = `${url.origin}/chatbot/knowledge-base.json`;
35	    const kbRes   = await env.ASSETS.fetch(new Request(kbUrl));
36	    kb            = await kbRes.json();
37	  } catch (err) {
38	    return json({ success: false, error: 'Knowledge base not found' }, 500);
39	  }
40	
41	  // ── Route actions ──────────────────────────────────────────
42	  const url    = new URL(request.url);
43	  const action = url.searchParams.get('action') || 'search';
44	
45	  switch (action) {
46	
47	    case 'all':
48	      return json({ success: true, data: kb });
49	
50	    case 'faq': {
51	      const category = url.searchParams.get('category');
52	      let faqs = kb.faq || [];
53	      if (category) faqs = faqs.filter(f => f.category === category);
54	      return json({ success: true, count: faqs.length, data: faqs });
55	    }
56	
57	    case 'category': {
58	      const cat = (url.searchParams.get('cat') || '').toLowerCase().trim();
59	      if (!cat) return json({ success: false, error: 'Missing category parameter' });
60	      const results = (kb.faq || []).filter(f => f.category === cat);
61	      return json({ success: true, category: cat, count: results.length, data: results });
62	    }
63	
64	    case 'service': {
65	      const name     = (url.searchParams.get('name') || '').toLowerCase().trim();
66	      const services = kb.services || {};
67	      if (!name) return json({ success: false, error: 'Missing service name' });
68	
69	      if (services[name]) return json({ success: true, data: services[name] });
70	
71	      // Partial match
72	      const entry = Object.entries(services).find(
73	        ([k]) => k.includes(name) || name.includes(k)
74	      );
75	      if (entry) return json({ success: true, service_key: entry[0], data: entry[1] });
76	
77	      return json({ success: false, error: 'Service not found', available: Object.keys(services) });
78	    }
79	
80	    case 'contact':
81	      return json({ success: true, data: kb.company?.contact || {} });
82	
83	    case 'company':
84	      return json({ success: true, data: kb.company || {} });
85	
86	    case 'search':
87	    case 'chat': {
88	      let query = '';
89	
90	      if (request.method === 'POST') {
91	        const body = await request.json().catch(() => ({}));
92	        query = (body.q || body.query || body.message || '').toLowerCase().trim();
93	      } else {
94	        query = (url.searchParams.get('q') || url.searchParams.get('query') || '').toLowerCase().trim();
95	      }
96	
97	      if (!query) return json({ success: false, error: 'Missing query parameter (q or query)' });
98	
99	      const results = searchKnowledgeBase(kb, query);
100	
101	      if (action === 'chat') {
102	        const response = buildChatResponse(kb, query, results);
103	        return json({ success: true, query, response, sources: results });
104	      }
105	      return json({ success: true, query, count: results.length, results });
106	    }
107	
108	    default:
109	      return json({
110	        success: false,
111	        error: 'Unknown action',
112	        available_actions: ['all', 'faq', 'category', 'service', 'contact', 'company', 'search', 'chat'],
113	      });
114	  }
115	}
116	
117	// ── Helpers ────────────────────────────────────────────────────
118	
119	function json(data, status = 200) {
120	  return new Response(JSON.stringify(data), { status, headers: CORS_HEADERS });
121	}
