123	/**
124	 * Search the knowledge base for relevant entries
125	 */
126	function searchKnowledgeBase(kb, query) {
127	  const results    = [];
128	  const queryWords = query.split(' ').filter(w => w.length > 2);
129	
130	  // Search FAQ
131	  for (const faq of (kb.faq || [])) {
132	    const text  = `${faq.question} ${faq.answer} ${(faq.keywords || []).join(' ')}`;
133	    const score = scoreEntry(text, queryWords, query);
134	    if (score > 0) {
135	      results.push({
136	        type    : 'faq',
137	        id      : faq.id,
138	        category: faq.category,
139	        question: faq.question,
140	        answer  : faq.answer,
141	        score,
142	      });
143	    }
144	  }
145	
146	  // Search services
147	  for (const [serviceKey, service] of Object.entries(kb.services || {})) {
148	    let searchText = `${service.name} ${service.description}`;
149	    if (service.features) searchText += ` ${service.features.join(' ')}`;
150	    if (service.benefits) searchText += ` ${service.benefits.join(' ')}`;
151	    if (service.solutions) {
152	      for (const sol of service.solutions) {
153	        searchText += ` ${sol.name} ${sol.description}`;
154	      }
155	    }
156	
157	    const score = scoreEntry(searchText, queryWords, query);
158	    if (score > 0) {
159	      results.push({
160	        type       : 'service',
161	        service_key: serviceKey,
162	        name       : service.name,
163	        description: service.description,
164	        page_url   : service.page_url ?? null,
165	        score,
166	      });
167	    }
168	  }
169	
170	  // Search company info
171	  const company      = kb.company || {};
172	  const companyText  = `${company.name} ${company.description} ${(company.key_messages || []).join(' ')}`;
173	  const companyScore = scoreEntry(companyText, queryWords, query);
174	  if (companyScore > 0) {
175	    results.push({
176	      type : 'company',
177	      data : {
178	        name       : company.name,
179	        description: company.description,
180	        contact    : company.contact,
181	        address    : company.address,
182	      },
183	      score: companyScore,
184	    });
185	  }
186	
187	  // Sort by score and return top 5
188	  results.sort((a, b) => b.score - a.score);
189	  return results.slice(0, 5);
190	}
