192	/**
193	 * Score relevance of text to query
194	 */
195	function scoreEntry(text, queryWords, fullQuery) {
196	  text = text.toLowerCase();
197	  let score = 0;
198	
199	  // Exact phrase match (highest score)
200	  if (text.includes(fullQuery)) score += 20;
201	
202	  // Individual word matches
203	  for (const word of queryWords) {
204	    if (text.includes(word)) score += 3;
205	  }
206	
207	  // Greek/English transliteration helpers
208	  const transliterations = {
209	    energy    : 'ενέργεια ρεύμα αέριο',
210	    office    : 'γραφείο έδρα virtual',
211	    'call center': 'τηλεφωνικό κέντρο',
212	    price     : 'τιμή κόστος τιμολόγιο',
213	    cheap     : 'φθηνό εξοικονόμηση',
214	    crm       : 'crm erp τεχνολογία',
215	    partner   : 'συνεργάτης συνεργασία',
216	    career    : 'καριέρα θέση εργασία',
217	    contact   : 'επικοινωνία τηλέφωνο email',
218	  };
219	
220	  for (const [en, gr] of Object.entries(transliterations)) {
221	    if (fullQuery.includes(en) && (text.includes(gr) || text.includes(en))) {
222	      score += 5;
223	    }
224	  }
225	
226	  return score;
227	}
